UA = {"User-Agent": "python-urllib/3"}
def get(url, tries=3, timeout=40):
    for i in range(tries):
        try:
            req = urllib.request.Request(url, headers=UA)
            return urllib.request.urlopen(req, timeout=timeout).read()
        except Exception as e:
            err = e; time.sleep(2+2*i)
    raise err

def crossref(q, rows=5, **kw):
    params = {"query.bibliographic": q, "rows": rows,
              "select": "title,author,container-title,issued,DOI,type,page,volume,publisher,event"}
    if MAIL: params["mailto"] = MAIL
    params.update(kw)
    u = "https://api.crossref.org/works?" + urllib.parse.urlencode(params)
    d = json.loads(get(u))
    out = []
    for it in d["message"]["items"]:
        out.append({
            "title": (it.get("title") or [""])[0],
            "authors": "; ".join(f"{a.get('family','')} {a.get('given','')}".strip() for a in it.get("author", [])[:4]),
            "venue": (it.get("container-title") or it.get("event",{}).get("name") or [""] if isinstance(it.get("container-title"), list) else "") ,
            "container": (it.get("container-title") or [""])[0] if it.get("container-title") else (it.get("event",{}) or {}).get("name",""),
            "year": (it.get("issued",{}).get("date-parts") or [[None]])[0][0],
            "doi": it.get("DOI"), "type": it.get("type"),
            "vol": it.get("volume"), "page": it.get("page"), "publisher": it.get("publisher"),
        })
    return out

def dblp(q, h=8):
    u = "https://dblp.org/search/publ/api?" + urllib.parse.urlencode({"q": q, "format":"json", "h":h})
    d = json.loads(get(u))
    hits = d.get("result",{}).get("hits",{}).get("hit",[])
    out=[]
    for x in hits:
        i = x["info"]
        a = i.get("authors",{}).get("author",[])
        if isinstance(a, dict): a=[a]
        out.append({"title": i.get("title"), "authors": "; ".join(y["text"] for y in a[:5]),
                    "venue": i.get("venue"), "year": i.get("year"), "type": i.get("type"),
                    "doi": i.get("doi"), "url": i.get("ee")})
    return out

